import{_ as t,o,c as a,a3 as s}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"Connect OpenCode to Wake","description":"How to connect a repository to OpenCode with wake connect opencode: its commands, plugin and skills, the files it writes, signing in and updates.","frontmatter":{"title":"Connect OpenCode to Wake","description":"How to connect a repository to OpenCode with wake connect opencode: its commands, plugin and skills, the files it writes, signing in and updates."},"headers":[],"relativePath":"agents/opencode.md","filePath":"agents/opencode.md","lastUpdated":1794486859000}'),n={name:"agents/opencode.md"};function i(d,e,c,h,l,r){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h1><p>Connect a repository to OpenCode from its directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span></code></pre></div><p><code>wake setup --agent opencode</code> runs it for you. Commit the files it writes.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>Five commands you type in OpenCode:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/wake-next</code></td><td>Proposes the next free task and claims it once you confirm</td></tr><tr><td><code>/wake-status</code></td><td>Shows the tasks this session holds, the free ones and what is left in the open milestone; changes nothing</td></tr><tr><td><code>/wake-plan &lt;idea&gt;</code></td><td>Plans the idea with the repository&#39;s planning method, without writing code</td></tr><tr><td><code>/wake-done</code></td><td>Runs the repository&#39;s checks, attaches evidence and completes the task this session holds</td></tr><tr><td><code>/wake-release</code></td><td>Releases the open milestone with the repository&#39;s own process, asking before every push, tag or publish</td></tr></tbody></table><p>The <code>wake</code> and <code>wake-planning</code> skills tell OpenCode how to claim, plan and finish work. A plugin runs <code>wake hook</code> when a session starts, after each tool call and when it ends, with the <a href="/wake-dist/docs/start/cli#sign-in">CLI&#39;s sign-in</a>, so the CLI must be installed and signed in on this machine.</p><h2 id="files-it-writes" tabindex="-1">Files it writes <a class="header-anchor" href="#files-it-writes" aria-label="Permalink to &quot;Files it writes&quot;">​</a></h2><ul><li><code>opencode.jsonc</code> (or <code>opencode.json</code> when the repository has that one): Wake&#39;s MCP server, <code>wake</code>, at <code>&lt;your Wake URL&gt;/mcp</code>.</li><li><code>.opencode/plugins/wake.ts</code>: the plugin that runs the hooks.</li><li><code>.opencode/commands/wake-next.md</code>, <code>wake-status.md</code>, <code>wake-plan.md</code>, <code>wake-done.md</code> and <code>wake-release.md</code>: the commands.</li><li><code>.agents/skills/wake/SKILL.md</code> and <code>.agents/skills/wake-planning/SKILL.md</code>: the skills, one copy shared with Pi and Codex.</li><li>The Wake block in <code>AGENTS.md</code>, or in <code>CLAUDE.md</code> when the repository has only that one.</li></ul><p>No file holds a token.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wake</span></span></code></pre></div><p>Allow OpenCode in the browser.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>The CLI updates OpenCode&#39;s files. After you <a href="/wake-dist/docs/start/cli#update-the-cli">update the CLI</a>, the next session start brings the files above up to the CLI&#39;s version, as <code>wake connect opencode</code> would, and the agent&#39;s context names the files to commit. It skips the update when you edited one of those files, or when they come from a newer Wake than your CLI, and says why instead: it never overwrites an edit or downgrades a teammate.</p><p>To update only by hand, set <code>WAKE_ADAPTER_UPDATES=off</code> in the agent&#39;s environment. The session start then says to run <code>wake connect opencode</code> when a newer version is available.</p>',17)])])}const u=t(n,[["render",i]]);export{k as __pageData,u as default};
